-- Atlas RAM · V15: servicio del paciente (consulta externa, emergencia, hospitalización, UCI).
--
-- CLSI M39 recomienda antibiogramas estratificados por unidad, sobre todo UCI: la resistencia en cuidados
-- intensivos es mayor y el tratamiento empírico de esos pacientes no debe guiarse por el promedio del hospital.
-- La columna es opcional porque no todos los laboratorios informan el servicio.

alter table isolate add column ward varchar(20)
    check (ward in ('OUTPATIENT', 'EMERGENCY', 'INPATIENT', 'ICU'));
create index idx_isolate_ward on isolate (ward) where ward is not null;

-- Datos del seed: el generador ya decidía el servicio de cada aislamiento sintético (la probabilidad de
-- resistencia depende de él), pero no lo guardaba. Se cruza por id y fecha de toma, así que en una base que no
-- salió del seed esta sentencia no cambia nada. Solo datos SINTÉTICOS.
UPDATE isolate i SET ward = CASE v.w WHEN 'O' THEN 'OUTPATIENT' WHEN 'E' THEN 'EMERGENCY' WHEN 'H' THEN 'INPATIENT' ELSE 'ICU' END
